    let score = dot(normal, -rotateByQuaternion(vec3<f32>(0.0, -1.0, 0.0), decal.projectorRotation));
    if (score > bestScore) {
      bestScore = score;
      uv = vec2<f32>(
        projectorPosition.x * projectorScaleForAxis(decal.sizeDepthPadding.x, decal.projectorScale.x),
        projectorPosition.z * projectorScaleForAxis(decal.sizeDepthPadding.y, decal.projectorScale.z)
      ) + vec2<f32>(0.5);
    }
