  let skyHalfDirection = normalize(viewDirection + directLightDirection);
  let skySpecularNdotH = max(dot(normal, skyHalfDirection), 0.0);
  let skySpecularStrength = pow(skySpecularNdotH, directSpecularExponent) * mix(1.0, 0.2, roughness);
  let skySpecular = skyLight * directSpecularColor * skySpecularStrength;
